  if (f.browsingOwns && !shift && key === 'g') return 'chord-arm!P';
  if (key === 's' && !shift && !repeat && (f.browsingOwns || readerIsOpen) && !f.shortcutBlocked) return `${x.starCond ? 'unstar' : 'star'}!P`;
  if (key === 'E' && shift && !f.shortcutBlocked) return 'unarchive!P';
  if (key === 'U' && shift && !f.shortcutBlocked) return 'unread!P';
  if (key === 'c' && !shift && !repeat && (f.browsingOwns || readerIsOpen) && (!f.shortcutBlocked || f.draftsRowOwns)) return 'compose!P';
  if (key === 'r' && !shift && !repeat && readerIsOpen && !f.shortcutBlocked) return x.availReply ? 'reply!P' : N;
  if (key === 'z' && !shift && !f.shortcutBlocked) { if (repeat) return N; return 'undo!P'; }
  if (readerIsOpen) {
